        public static InteractionTier GetMatrixInteraction(int senderIdx, int receiverIdx)
        {
            if (senderIdx < 0 || senderIdx >= 10 || receiverIdx < 0 || receiverIdx >= 10)
                return InteractionTier.Incompatible;
            return DatalinkMatrix[senderIdx, receiverIdx];
        }

        public static int StandardToIndex(DatalinkStandard s)
        {
            switch (s)
            {
                case DatalinkStandard.Usg2Cec: return 0;
                case DatalinkStandard.Ttnt: return 1;
                case DatalinkStandard.Link16: return 2;
                case DatalinkStandard.Link11: return 3;
                case DatalinkStandard.Ifdl: return 4;
                case DatalinkStandard.Madl: return 5;
                case DatalinkStandard.Jsidls: return 6;
                case DatalinkStandard.Hn900: return 7;
                case DatalinkStandard.RuFortTvm: return 8;
                case DatalinkStandard.Tks2Apd518: return 9;
                default: return -1;
            }
        }

        public static InteractionTier QueryDatalinkMatrix(DatalinkStandard s1, DatalinkStandard s2)
        {
            if (s1 == DatalinkStandard.None || s2 == DatalinkStandard.None)
                return InteractionTier.Incompatible;

            if (s1 == DatalinkStandard.SatcomUplink || s2 == DatalinkStandard.SatcomUplink)
                return InteractionTier.SatcomGlobal;

            if (s1 == DatalinkStandard.RuNavalTactical || s2 == DatalinkStandard.RuNavalTactical)
            {
                bool s1Ru = s1 == DatalinkStandard.RuNavalTactical || s1 == DatalinkStandard.RuFortTvm || s1 == DatalinkStandard.Tks2Apd518;
                bool s2Ru = s2 == DatalinkStandard.RuNavalTactical || s2 == DatalinkStandard.RuFortTvm || s2 == DatalinkStandard.Tks2Apd518;
                return (s1Ru && s2Ru) ? InteractionTier.Tier3_TrackRelay : InteractionTier.Incompatible;
            }

            int idx1 = StandardToIndex(s1);
            int idx2 = StandardToIndex(s2);
            if (idx1 >= 0 && idx2 >= 0)
                return DatalinkMatrix[idx1, idx2];

            return InteractionTier.Incompatible;
        }

        public static IEnumerable<DatalinkStandard> GetIndividualStandards(DatalinkStandard standard)
        {
            if (standard == DatalinkStandard.None)
                yield break;
            for (int i = 0; i < 12; i++)
            {
                DatalinkStandard bit = (DatalinkStandard)(1 << i);
                if ((standard & bit) != 0)
                    yield return bit;
            }
        }
    }
}
